#include <cstdio>
#include <map>
#include <vector>

using namespace std;

int main() {
    int n, m;
    while (scanf("%d", &n), n) {
        char a, b;
        vector<char> str; // Use vector for efficient appending
        map<char, char> to;

        for (int i = 0; i < n; ++i) {
            scanf(" %c %c", &a, &b);
            to[a] = b;
        }

        scanf("%d", &m);
        for (int i = 0; i < m; ++i) {
            scanf(" %c", &a);
            if (to.count(a)) a = to[a];
            str.push_back(a); // Append to vector instead of string
        }

        printf("%.*s\n", (int)str.size(), str.data()); // Print using vector data
    }
    return 0;
}

